-- chair-step: inverse of read_lane_v2_b3_59_runtime_operation_stream_batch — un-enrolls runtime.operation_stream_batch from read-lane v2 and regenerates it back to the set-form read lane.
delete from iam.read_lane_v2_rollout where token = (select token from platform.entity_types where schema_name = 'runtime' and table_name = 'operation_stream_batch' and is_active);
select iam.apply_rls('runtime', 'operation_stream_batch', (select token from platform.entity_types where schema_name = 'runtime' and table_name = 'operation_stream_batch' and is_active), (select rls_variant from platform.entity_types where schema_name = 'runtime' and table_name = 'operation_stream_batch' and is_active));
